    init_array(n, A, B);

    // Create ImageParams for A and B so that Halide pipelines can read them.
    ImageParam A_param(type_of<num_t>(), 3, "A_param");
    ImageParam B_param(type_of<num_t>(), 3, "B_param");

    A_param.set(A);
    B_param.set(B);

    // Vars for 3D indexing (k, j, i) <-> (C's k, j, i).
    Var k("k"), j("j"), i("i");

