    // Schedule: optimize each stencil for data locality and parallelism.
    //
    //  - k is the fastest-varying dimension in memory; we vectorize it.
    //  - j and i are tiled and fused into a single parallel dimension,
    //    so different tiles run on different cores.
    //  - The schedule is identical for B_from_A and A_from_B.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        // Reasonable fallback if natural_vector_size is not available.
        vec_width = 8;
    }

