    const int tile_j = 4;  // tile size in j (second dim)
    const int tile_i = 4;  // tile size in i (third dim)

    // Schedule for B_from_A: B = stencil(A)
    B_from_A
        .compute_root()
        // Tile the (j,i) plane into 2D tiles, then fuse the tile indices
        // into a single parallel dimension.
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
