        // Make k innermost (vectorized), then the intra-tile j/i loops.
        .reorder(k, ji, ii, tile_xy)
        // Parallelize over tiles in the (j,i) plane.
        .parallel(tile_xy)
        // Vectorize across k (fastest dimension in memory).
