    A_from_B
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile_xy)
        .reorder(k, ji, ii, tile_xy)
        .parallel(tile_xy)
        .vectorize(k, vec_width);

    // Compile the kernels ahead of time to avoid measuring JIT cost.
    B_from_A.compile_jit(target);
    A_from_B.compile_jit(target);

